import { FeltDBErrorCode, FeltDBServiceError } from './error-codes.js';
export function normalizeAuthorityScope(scope) {
    if (!scope) {
        throw new FeltDBServiceError('An explicit tenant or platform authority scope is required', FeltDBErrorCode.AUTHORITY_SCOPE_REQUIRED);
    }
    if (scope.kind === 'platform') {
        const tenantIds = [...new Set((scope.tenantIds ?? []).map(value => value.trim()))];
        if (tenantIds.some(value => !value)) {
            throw new FeltDBServiceError('Platform tenantIds must be non-empty strings', FeltDBErrorCode.AUTHORITY_SCOPE_INVALID);
        }
        return { kind: 'platform', tenantIds };
    }
    if (scope.kind !== 'tenant' || typeof scope.tenantId !== 'string' || !scope.tenantId.trim()) {
        throw new FeltDBServiceError('Tenant authority requires a non-empty tenantId', FeltDBErrorCode.AUTHORITY_SCOPE_REQUIRED);
    }
    if (scope.environmentId !== undefined && (typeof scope.environmentId !== 'string' || !scope.environmentId.trim())) {
        throw new FeltDBServiceError('environmentId must be a non-empty string when provided', FeltDBErrorCode.AUTHORITY_SCOPE_INVALID);
    }
    return {
        kind: 'tenant',
        tenantId: scope.tenantId.trim(),
        ...(scope.environmentId ? { environmentId: scope.environmentId.trim() } : {}),
    };
}
export function authorityScopeKey(scope) {
    const pathSafe = (value) => Array.from(new TextEncoder().encode(value), byte => byte.toString(16).padStart(2, '0')).join('');
    return scope.kind === 'platform'
        ? 'platform'
        : `tenant/${pathSafe(scope.tenantId)}/${pathSafe(scope.environmentId ?? 'default')}`;
}
export function sameAuthorityScope(left, right) {
    return left.kind === right.kind && (left.kind === 'platform'
        || (right.kind === 'tenant' && left.tenantId === right.tenantId && left.environmentId === right.environmentId));
}
export function assertAuthorityScope(expected, actual) {
    if (!sameAuthorityScope(expected, normalizeAuthorityScope(actual))) {
        throw new FeltDBServiceError('Operation authority scope does not match the bound session', FeltDBErrorCode.AUTHORITY_SCOPE_MISMATCH);
    }
}
